const productMap = buildProductMap()

const STORAGE_PREFIX = 'hobags_product_override_'

function loadOverrides(): void {
  if (typeof localStorage === 'undefined') return
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i)
    if (key?.startsWith(STORAGE_PREFIX)) {
      const id = key.slice(STORAGE_PREFIX.length)
      try {
        const raw = localStorage.getItem(key)
        if (raw) {
          const data = JSON.parse(raw)
          if (data && data.id) {
            productMap.set(id, data)
          }
        }
      } catch { /* skip corrupt entries */ }
    }
  }
}
loadOverrides()

export function getProductById(id: string): Product | undefined {
  return productMap.get(id)
}

export function getProductsByCategory(category: string): Product[] {
  return Array.from(productMap.values()).filter(p =>
    p.category.toLowerCase() === category.toLowerCase()
  )
}

export function getRelatedProducts(productId: string, limit: number = 4): Product[] {
  const product = getProductById(productId)
  if (!product) return []
  return Array.from(productMap.values())
    .filter(p => p.id !== productId && p.category === product.category)
    .slice(0, limit)
}

export function updateProductInLookup(updated: Product): void {
  productMap.set(updated.id, updated)
  try {
    localStorage.setItem(STORAGE_PREFIX + updated.id, JSON.stringify(updated))
  } catch { /* localStorage may be full or unavailable */ }
}
